package app.veyra;
import android.app.Activity;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;
@androidx.annotation.OptIn(markerClass=androidx.media3.common.util.UnstableApi.class)
public final class DownloadsActivity extends Activity {
 private LinearLayout body;private String snapshot="";private final Handler handler=new Handler(Looper.getMainLooper());private final Runnable update=new Runnable(){public void run(){render();handler.postDelayed(this,2000);}};
 public void onCreate(Bundle saved){super.onCreate(saved);Ui.configure(this);LinearLayout root=Ui.column(this);Button back=Ui.quiet(this,"‹  Downloads");back.setOnClickListener(v->finish());root.addView(back);root.addView(Ui.text(this,"Stories to take with you",28,Ui.INK));root.addView(Ui.text(this,"Completed downloads play without a connection. Keep at least 256 MB free; each download is limited to 8 GB. Downloaded renditions and captions depend on the stream.",13,Ui.MUTED));if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED){Button notifications=Ui.quiet(this,"Enable download notifications");notifications.setOnClickListener(v->requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},81));root.addView(notifications);}
ScrollView scroll=new ScrollView(this);body=Ui.column(this);scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);Ui.insets(this,root,20);}
 private void render(){java.util.List<JSONObject> entries=OfflineStore.list(this);String next=entries.toString()+DownloadWorker.active();if(next.equals(snapshot))return;snapshot=next;body.removeAllViews();if(entries.isEmpty())body.addView(Ui.text(this,"Open a title and tap Download on the movie or episode you want to save.",17,Ui.MUTED));for(JSONObject record:entries){String id=record.optString("downloadId");LinearLayout card=Ui.card(this);card.addView(Ui.text(this,record.optString("title"),18,Ui.INK));String state=record.optString("state");if(state.equals("downloading")&&!DownloadWorker.isActive(id))state="interrupted";card.addView(Ui.text(this,state.equals("downloading")?record.optInt("percent")+"% · downloading":state.equals("complete")?"Available offline":state+" · open the title to retry",13,Ui.MUTED));LinearLayout actions=new LinearLayout(this);if(state.equals("complete")){Button play=Ui.primary(this,"Play offline");play.setOnClickListener(v->startActivity(new Intent(this,PlayerActivity.class).putExtra("offlineId",id)));actions.addView(play);}Button remove=Ui.quiet(this,DownloadWorker.isActive(id)?"Cancel":"Delete");remove.setOnClickListener(v->{if(DownloadWorker.isActive(id))startService(new Intent(this,DownloadWorker.class).setAction("cancel"));else ActionSheet.show(this,"Remove download?",new String[]{"Delete downloaded media","Keep download"},index->{if(index==0)new Thread(()->{try{OfflineStore.remove(this,id);runOnUiThread(this::render);}catch(Exception ignored){runOnUiThread(()->Toast.makeText(this,"Close playback before deleting this download",Toast.LENGTH_LONG).show());}}).start();});});actions.addView(remove);card.addView(actions);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=Ui.dp(this,12);body.addView(card,lp);}}
 protected void onStart(){super.onStart();handler.post(update);}protected void onStop(){handler.removeCallbacks(update);super.onStop();}
}
